-- Wat is nieuw: Microsoft To Do-taken in Mijn acties (live op 15-10-2026).
insert into public.changelog (datum, categorie, module, titel, omschrijving, doelgroep) values
  ('2026-10-15','nieuw','Acties','Je taken uit Microsoft To Do staan in Mijn acties',
   'Taken die je in To Do of Outlook aanmaakt, zie je nu ook in Mijn acties, per lijst gegroepeerd. Vink je ze hier af of geef je ze een andere titel of deadline, dan gaat dat in To Do mee, en andersom. Met "Lijsten" kies je welke lijsten meedoen; gedeelde lijsten staan standaard uit, omdat daar ook de taken van collega''s in staan.',
   'kantoor');
